finding:
cerr << "
Cannot find valid MBR data on '" << device << "'! Exiting!

"; exit(1); break;

cerr << "
Cannot determine the validity of the disk on '" << device << "'! Exiting!

"; exit(1);

cerr << "\aCaution: invalid backup GPT header, but valid main header; regenerating
" << "backup header from main header.

"; RebuildSecondHeader();

cerr << "\aCaution: invalid main GPT header, but valid backup; regenerating main header
" << "from backup!

"; RebuildMainHeader();

cerr << "Warning! Main and backup partition tables differ! Use the 'c' and 'e' options
" << "on the recovery & transformation menu to examine the two tables.

"; allOK = 0;
